module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

    parameter INCREMENT = 2'b00;
    parameter DECREMENT = 2'b01;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= INCREMENT;
            wave <= 5'b00000;
        end else begin
            case (state)
                INCREMENT: begin
                    if (wave == 5'b11111) begin
                        state <= DECREMENT;
                    end else begin
                        wave <= wave + 1;
                    end
                end
                DECREMENT: begin
                    if (wave == 5'b00000) begin
                        state <= INCREMENT;
                    end else begin
                        wave <= wave - 1;
                    end
                end
                default: state <= INCREMENT;
            endcase
        end
    end

endmodule
